// ─── File: PolyglotBankingDemo.java ───
// Runnable demo. Each store is a package-private class standing in for a real engine.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PolyglotBankingDemo {

    private static final Logger log = Logger.getLogger("polyglot");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        RelationalAccountStore sql = new RelationalAccountStore();   // PostgreSQL stand-in
        NoSqlHistoryStore nosql = new NoSqlHistoryStore();           // Cassandra stand-in
        RedisCache cache = new RedisCache(30_000);                   // Redis, 30s TTL

        BankingFacade bank = new BankingFacade(sql, nosql, cache);

        // Atomic transfer in SQL + history append in NoSQL + cache invalidation.
        bank.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        // First balance read: cache MISS → read SQL → populate Redis.
        bank.readBalance("SAV2001");
        // Second read: cache HIT → served from Redis, no SQL touched.
        bank.readBalance("SAV2001");

        // A failing transfer must leave SQL unchanged (ACID atomicity).
        try {
            bank.transfer("CUR3001", "SAV2001", new BigDecimal("9999999"));
        } catch (RuntimeException e) {
            log.severe(() -> "transfer rejected: " + e.getMessage() + " (balances unchanged)");
        }
    }
}

// ─── model/Account.java ───
class Account {
    final String accountId; final String holderName; BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal amt) {
        if (balance.compareTo(amt) < 0) throw new IllegalStateException("insufficient funds in " + accountId);
        balance = balance.subtract(amt);
    }
    void credit(BigDecimal amt) { balance = balance.add(amt); }
}

// ─── store/RelationalAccountStore.java — ACID / strong consistency ───
class RelationalAccountStore {
    private static final Logger log = Logger.getLogger("polyglot");
    private final Map<String, Account> rows = new HashMap<>();
    RelationalAccountStore() {
        rows.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        rows.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    // Simulated single ACID transaction: both legs commit or neither does.
    synchronized void atomicTransfer(String fromId, String toId, BigDecimal amount) {
        Account from = rows.get(fromId), to = rows.get(toId);
        BigDecimal fromBefore = from.balance, toBefore = to.balance;
        try {
            from.debit(amount);
            to.credit(amount);
            log.info(() -> "[SQL] COMMIT " + fromId + " " + fromBefore + "->" + from.balance
                    + ", " + toId + " " + toBefore + "->" + to.balance);
        } catch (RuntimeException e) {
            from.balance = fromBefore; to.balance = toBefore;   // rollback
            log.warning("[SQL] ROLLBACK — no money moved");
            throw e;
        }
    }
    BigDecimal balanceOf(String id) { return rows.get(id).balance; }
}

// ─── store/NoSqlHistoryStore.java — append-only, flexible schema, no joins ───
class NoSqlHistoryStore {
    private static final Logger log = Logger.getLogger("polyglot");
    private final List<Map<String, Object>> documents = new ArrayList<>();
    void append(String accountId, String direction, BigDecimal amount, String txnId) {
        Map<String, Object> doc = new LinkedHashMap<>();  // flexible-shape document
        doc.put("accountId", accountId);
        doc.put("direction", direction);
        doc.put("amount", amount);
        doc.put("txnId", txnId);
        doc.put("ts", System.currentTimeMillis());
        documents.add(doc);   // pure write, horizontally scalable, no transaction needed
        log.info(() -> "[NoSQL] appended history " + direction + " Rs." + amount + " acct=" + accountId);
    }
}

// ─── cache/RedisCache.java — cache-aside with TTL ───
class RedisCache {
    private static final Logger log = Logger.getLogger("polyglot");
    private final Map<String, BigDecimal> store = new HashMap<>();
    private final Map<String, Long> expiry = new HashMap<>();
    private final long ttlMillis;
    RedisCache(long ttlMillis) { this.ttlMillis = ttlMillis; }
    BigDecimal get(String key) {
        Long exp = expiry.get(key);
            if (exp == null || exp < System.currentTimeMillis()) { store.remove(key);
            return null; }
        return store.get(key);
    }
    void put(String key, BigDecimal value) {
        store.put(key, value);
        expiry.put(key, System.currentTimeMillis() + ttlMillis);
    }
    void evict(String key) { store.remove(key); expiry.remove(key);
        log.fine(() -> "[Redis] evicted " + key); }
}

// ─── facade/BankingFacade.java — ties the three engines together ───
class BankingFacade {
    private static final Logger log = Logger.getLogger("polyglot");
    private final RelationalAccountStore sql;
    private final NoSqlHistoryStore nosql;
    private final RedisCache cache;
    BankingFacade(RelationalAccountStore sql, NoSqlHistoryStore nosql, RedisCache cache) {
            this.sql = sql;
            this.nosql = nosql
            this.cache = cache;
    }
    void transfer(String from, String to, BigDecimal amount) {
        String txnId = "TXN-" + UUID.randomUUID().toString().substring(0, 8);
        sql.atomicTransfer(from, to, amount);            // strong consistency (money)
        nosql.append(from, "DEBIT", amount, txnId);      // scalable history (append-only)
        nosql.append(to, "CREDIT", amount, txnId);
        cache.evict("balance:" + from);                  // keep cache fresh
        cache.evict("balance:" + to);
    }
    BigDecimal readBalance(String accountId) {
        String key = "balance:" + accountId;
        BigDecimal cached = cache.get(key);
        if (cached != null) {
            log.info(() -> "[Redis HIT] balance " + accountId + " = Rs." + cached);
            return cached;
        }
        BigDecimal fresh = sql.balanceOf(accountId);     // cache miss → source of truth
        cache.put(key, fresh);
        log.info(() -> "[Redis MISS] read SQL, cached balance " + accountId + " = Rs." + fresh);
        return fresh;
    }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
